// Fictional sample data only; example.invalid addresses cannot receive mail.
return [{json: {
  batchId: 'demo-batch-001',
  existingContacts: [
    {email:'existing@example.invalid', crmId:'demo-crm-1'},
    {email:'ambiguous@example.invalid', crmId:'demo-crm-2'},
    {email:'ambiguous@example.invalid', crmId:'demo-crm-3'}
  ],
  records: [
    {sourceId:'row-1', email:' NEW@example.invalid ', company:'Sample Alpha'},
    {sourceId:'row-2', email:'new@example.invalid', company:'Sample Alpha'},
    {sourceId:'row-3', email:'conflict@example.invalid', company:'Sample Beta'},
    {sourceId:'row-4', email:'conflict@example.invalid', company:'Different Sample'},
    {sourceId:'row-5', email:'existing@example.invalid', company:'Sample Existing'},
    {sourceId:'row-6', email:'ambiguous@example.invalid', company:'Sample Ambiguous'},
    {sourceId:'row-7', email:'not-an-address', company:'Sample Invalid'},
    {sourceId:'row-8', email:'missingcompany@example.invalid', company:''},
    {sourceId:'row-9', email:'other@example.invalid', company:'Sample Other'},
    {sourceId:'row-9', email:'another@example.invalid', company:'Sample Reused ID'}
  ]
}}];

// Preflight only: no writes, outreach, external calls, or durable deduplication.
const items = $input.all();
if (items.length !== 1) throw new Error('Supply exactly one batch envelope.');
const b = items[0].json;
if (typeof b.batchId !== 'string' || !b.batchId.trim()) throw new Error('batchId must be a non-empty string.');
if (!Array.isArray(b.records) || !Array.isArray(b.existingContacts)) throw new Error('records and existingContacts must be arrays.');
const emailKey = v => typeof v === 'string' ? v.trim().toLowerCase() : '';
const text = v => typeof v === 'string' ? v.trim() : '';
const emailShape = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const existing = new Map();
for (const c of b.existingContacts) {
  if (!c || typeof c !== 'object') throw new Error('Malformed existing contact.');
  const key = emailKey(c.email), id = text(c.crmId);
  if (!emailShape.test(key) || !id) throw new Error('Existing contacts need an email and crmId.');
  if (!existing.has(key)) existing.set(key, new Set());
  existing.get(key).add(id);
}
const rows = b.records.map((r, i) => {
  if (!r || typeof r !== 'object' || Array.isArray(r)) throw new Error('Each record must be an object.');
  return {sourceId:text(r.sourceId), email:emailKey(r.email), company:text(r.company), rowNumber:i+1};
});
const idCounts = new Map(), emailGroups = new Map();
for (const r of rows) {
  if (r.sourceId) idCounts.set(r.sourceId, (idCounts.get(r.sourceId)||0)+1);
  if (r.email) {
    if (!emailGroups.has(r.email)) emailGroups.set(r.email, []);
    emailGroups.get(r.email).push(r);
  }
}
const decisions = rows.map(r => {
  const reasons = [];
  if (!r.sourceId) reasons.push('missing_source_id');
  if (r.sourceId && idCounts.get(r.sourceId)>1) reasons.push('reused_source_id');
  if (!emailShape.test(r.email)) reasons.push('invalid_email_shape');
  if (!r.company) reasons.push('missing_company');
  const group = emailGroups.get(r.email)||[];
  if (new Set(group.map(x => x.company)).size>1) reasons.push('conflicting_batch_duplicates');
  const matches = existing.get(r.email)||new Set();
  if (matches.size>1) reasons.push('ambiguous_crm_match');
  let decision = reasons.length ? 'human_review' : 'ready_for_mapping';
  // Suppress duplicate rows only after checking every row in their group is valid.
  const groupHasInvalid = group.some(x => !x.sourceId || idCounts.get(x.sourceId)>1 || !x.company || !emailShape.test(x.email));
  if (!reasons.length && groupHasInvalid) {reasons.push('duplicate_group_has_invalid_row');decision='human_review';}
  if (!reasons.length && group.length>1 && group[0].rowNumber!==r.rowNumber) {
    decision='skip_identical_batch_duplicate';reasons.push('same_email_and_company_as_earlier_row');
  }
  return {...r, decision, reasons, proposedAction:decision==='ready_for_mapping' ? (matches.size===1?'map_existing':'map_new') : 'none', crmId:matches.size===1?[...matches][0]:null};
});
const summary = {total:decisions.length, ready_for_mapping:0, human_review:0, skip_identical_batch_duplicate:0};
for (const r of decisions) summary[r.decision]++;
return [{json:{batchId:b.batchId.trim(), summary, decisions, limitations:[
  'Only email and company are compared. Extend the comparison when mapping more fields.',
  'Email matching lowercases the entire address; change the policy if your source preserves case-sensitive local parts.',
  'Email shape is not mailbox verification or permission to contact anyone.',
  'An empty existingContacts array means no existing contacts were supplied, not that the CRM is empty.',
  'No CRM writes or durable idempotency ledger. Repeated runs only reproduce a preflight report.'
]}}];
